58	public class SevenToEightUpgradeHandler implements UpgradeHandler {
59	
60	  private static final Logger LOG = LoggerFactory.getLogger(SevenToEightUpgradeHandler.class);
61	
62	  @Override
63	  public Map<ConfigProperty, String> upgrade(HoodieWriteConfig config, HoodieEngineContext context,
64	                                             String instantTime, SupportsUpgradeDowngrade upgradeDowngradeHelper) {
65	    HoodieTable table = upgradeDowngradeHelper.getTable(config, context);
66	    HoodieTableMetaClient metaClient = table.getMetaClient();
67	    HoodieTableConfig tableConfig = metaClient.getTableConfig();
68	
69	    Map<ConfigProperty, String> tablePropsToAdd = new HashMap<>();
70	    tablePropsToAdd.put(HoodieTableConfig.TIMELINE_PATH, HoodieTableConfig.TIMELINE_PATH.defaultValue());
71	    upgradePartitionFields(config, tableConfig, tablePropsToAdd);
72	    upgradeMergeMode(tableConfig, tablePropsToAdd);
73	
74	    // Handle timeline upgrade:
75	    //  - Rewrite instants in active timeline to new format
76	    //  - TODO: Convert archived timeline to new LSM timeline format. It will be handled in a separate PR.
77	    List<HoodieInstant> instants = new ArrayList<>();
78	    try {
79	      // We need to move all the instants - not just completed ones.
80	      instants = metaClient.scanHoodieInstantsFromFileSystem(metaClient.getTimelinePath(),
81	          ActiveTimelineV1.VALID_EXTENSIONS_IN_ACTIVE_TIMELINE, false);
82	    } catch (IOException ioe) {
83	      LOG.error("Failed to get instants from filesystem", ioe);
84	      throw new HoodieIOException("Failed to get instants from filesystem", ioe);
85	    }
86	
87	    if (!instants.isEmpty()) {
88	      InstantFileNameGenerator instantFileNameGenerator = metaClient.getInstantFileNameGenerator();
89	      CommitMetadataSerDeV2 commitMetadataSerDeV2 = new CommitMetadataSerDeV2();
90	      CommitMetadataSerDeV1 commitMetadataSerDeV1 = new CommitMetadataSerDeV1();
91	      ActiveTimelineV2 activeTimelineV2 = new ActiveTimelineV2(metaClient);
92	      context.map(instants, instant -> {
93	        String originalFileName = instantFileNameGenerator.getFileName(instant);
94	        String replacedFileName = originalFileName;
95	        boolean isCompleted = instant.isCompleted();
96	        // Rename the metadata file name from the ${instant_time}.action[.state] format in version 0.x
97	        // to the ${instant_time}_${completion_time}.action[.state] format in version 1.x.
98	        if (isCompleted) {
99	          String completionTime = instant.getCompletionTime(); // this is the file modification time
100	          String startTime = instant.requestedTime();
101	          replacedFileName = replacedFileName.replace(startTime, startTime + UNDERSCORE + completionTime);
102	        }
103	        // Rename the action if necessary (e.g., REPLACE_COMMIT_ACTION to CLUSTERING_ACTION).
104	        // NOTE: New action names were only applied for pending instants. Completed instants do not have any change in action names.
105	        if (SIX_TO_EIGHT_TIMELINE_ACTION_MAP.containsKey(instant.getAction()) && !isCompleted) {
106	          replacedFileName = replacedFileName.replace(instant.getAction(), SIX_TO_EIGHT_TIMELINE_ACTION_MAP.get(instant.getAction()));
107	        }
108	        try {
109	          return renameTimelineV1InstantFileToV2Format(instant, metaClient, originalFileName, replacedFileName, commitMetadataSerDeV1, commitMetadataSerDeV2, activeTimelineV2);
110	        } catch (IOException e) {
111	          LOG.warn("Can not to complete the upgrade from version seven to version eight. The reason for failure is {}", e.getMessage());
112	        }
113	        return false;
114	      }, instants.size());
115	    }
116	
117	    return tablePropsToAdd;
118	  }
