559	  public static void create(HoodieStorage storage, StoragePath metadataFolder, Properties properties)
560	      throws IOException {
561	    if (!storage.exists(metadataFolder)) {
562	      storage.createDirectory(metadataFolder);
563	    }
564	    HoodieConfig hoodieConfig = new HoodieConfig(properties);
565	    StoragePath propertyPath = new StoragePath(metadataFolder, HOODIE_PROPERTIES_FILE);
566	    HoodieTableVersion tableVersion = getTableVersion(hoodieConfig);
567	    try (OutputStream outputStream = storage.create(propertyPath)) {
568	      if (!hoodieConfig.contains(NAME)) {
569	        throw new IllegalArgumentException(NAME.key() + " property needs to be specified");
570	      }
571	      hoodieConfig.setDefaultValue(TYPE);
572	      hoodieConfig.setDefaultValue(TIMELINE_HISTORY_PATH);
573	      hoodieConfig.setDefaultValue(TIMELINE_PATH);
574	      if (!hoodieConfig.contains(TIMELINE_LAYOUT_VERSION)) {
575	        // Use latest Version as default unless forced by client
576	        hoodieConfig.setValue(TIMELINE_LAYOUT_VERSION, TimelineLayoutVersion.CURR_VERSION.toString());
577	      }
578	      if (hoodieConfig.contains(BOOTSTRAP_BASE_PATH)) {
579	        if (tableVersion.greaterThan(HoodieTableVersion.SEVEN)) {
580	          hoodieConfig.setDefaultValue(BOOTSTRAP_INDEX_TYPE, BootstrapIndexType.getBootstrapIndexType(hoodieConfig).toString());
581	        } else {
582	          // Use the default bootstrap index class.
583	          hoodieConfig.setDefaultValue(BOOTSTRAP_INDEX_CLASS_NAME, BootstrapIndexType.getDefaultBootstrapIndexClassName(hoodieConfig));
584	        }
585	      }
586	      if (hoodieConfig.contains(TIMELINE_TIMEZONE)) {
587	        HoodieInstantTimeGenerator.setCommitTimeZone(HoodieTimelineTimeZone.valueOf(hoodieConfig.getString(TIMELINE_TIMEZONE)));
588	      }
589	      hoodieConfig.setDefaultValue(DROP_PARTITION_COLUMNS);
590	
591	      dropInvalidConfigs(hoodieConfig);
592	      storeProperties(hoodieConfig.getProps(), outputStream);
593	    }
594	  }
