597	    if (!props.containsKey(NAME.key())) {
598	      throw new IllegalArgumentException(NAME.key() + " property needs to be specified");
599	    }
600	    String table = props.getProperty(NAME.key());
601	    String database = props.getProperty(DATABASE_NAME.key(), "");
602	    return BinaryUtil.generateChecksum(getUTF8Bytes(String.format(TABLE_CHECKSUM_FORMAT, database, table)));
603	  }
