609	  static void dropInvalidConfigs(HoodieConfig config) {
610	    HoodieTableVersion tableVersion = getTableVersion(config);
611	    Map<String, ConfigProperty<?>> definedTableConfigs = HoodieTableConfig.definedTableConfigs()
612	        .stream().collect(Collectors.toMap(ConfigProperty::key, Function.identity()));
613	    List<String> invalidConfigs = config.getProps().keySet().stream()
614	        .map(k -> (String) k)
615	        // TODO: this can be eventually tightened to ensure all table configs are defined.
616	        .filter(key -> definedTableConfigs.containsKey(key)
617	            && !validateConfigVersion(definedTableConfigs.get(key), tableVersion))
618	        .collect(Collectors.toList());
619	    invalidConfigs.forEach(key -> {
620	      config.getProps().remove(key);
621	    });
622	  }
