624	  static boolean validateConfigVersion(ConfigProperty<?> configProperty, HoodieTableVersion tableVersion) {
625	    // TODO: this can be tightened up, once all configs have a since version.
626	    if (!configProperty.getSinceVersion().isPresent()) {
627	      return true;
628	    }
629	    // validate that the table version is greater than or equal to the config version
630	    HoodieTableVersion firstVersion = HoodieTableVersion.fromReleaseVersion(configProperty.getSinceVersion().get());
631	    boolean valid = tableVersion.greaterThan(firstVersion) || tableVersion.equals(firstVersion);
632	    if (!valid) {
633	      LOG.warn("Table version {} is lower than or equal to config's first version {}. Config {} will be ignored.",
634	          tableVersion, firstVersion, configProperty.key());
635	    }
636	    return valid;
637	  }
